<?php
namespace App\Services;use App\Models\NotificationLog;use App\Models\Order;use App\Models\OrderStatusEvent;use Illuminate\Support\Facades\DB;
class OrderLifecycleService{public function transition(Order $order,string $status,?int $userId=null,?string $message=null):void{$allowed=['pending_payment','confirmed','processing','packed','shipped','delivered','cancelled','return_requested','returned','refunded'];abort_unless(in_array($status,$allowed),422);DB::transaction(function()use($order,$status,$userId,$message){$order->lockForUpdate();$order->update(['status'=>$status]);OrderStatusEvent::create(['order_id'=>$order->id,'status'=>$status,'message'=>$message,'created_by'=>$userId,'occurred_at'=>now()]);foreach(array_filter([['email',$order->email],['sms',$order->phone]]) as [$channel,$recipient])if($recipient)NotificationLog::create(['order_id'=>$order->id,'channel'=>$channel,'recipient'=>$recipient,'template'=>'order_status_changed','payload'=>['order_number'=>$order->number,'status'=>$status]]);});}}
